package reviewreceipts

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"testing"
)

// The vectors are a byte-for-byte copy of
// tests/fixtures/review/review_receipt_vectors.json in mctlhq/mctl-agents at
// commit vectorsSourceCommit (mctl-agents#973). They are generated by the
// canonical Tier A Python (tests/test_review_parity_vectors.py); no expected
// value in this package's tests is computed by the code under test.
const (
	vectorsSourceCommit = "2684641c719b7c7b3944243f0f9ae1f70a238693"
	vectorsFile         = "testdata/review_receipt_vectors.json"
)

type docVector struct {
	Name     string          `json:"name"`
	Document json.RawMessage `json:"document"`
	Expected struct {
		ContentHash string `json:"content_hash"`
		ID          string `json:"id"`
	} `json:"expected"`
}

type refusalVector struct {
	Name     string          `json:"name"`
	Kind     string          `json:"kind"`
	Code     string          `json:"code"`
	Document json.RawMessage `json:"document"`
}

type acceptVector struct {
	Name       string          `json:"name"`
	Kind       string          `json:"kind"`
	Document   json.RawMessage `json:"document"`
	Normalised json.RawMessage `json:"normalised"`
}

type gateVector struct {
	Name              string            `json:"name"`
	Expected          string            `json:"expected"`
	Live              *json.RawMessage  `json:"live"`
	Request           *json.RawMessage  `json:"request"`
	Receipts          []json.RawMessage `json:"receipts"`
	RequiredAssurance string            `json:"required_assurance"`
}

type vectorFile struct {
	Documents struct {
		Requests []docVector `json:"requests"`
		Receipts []docVector `json:"receipts"`
	} `json:"documents"`
	ParseRefusals    []refusalVector `json:"parse_refusals"`
	ParseAcceptances []acceptVector  `json:"parse_acceptances"`
	Gate             []gateVector    `json:"gate"`
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	raw, err := os.ReadFile(vectorsFile)
	if err != nil {
		t.Fatal(err)
	}
	var v vectorFile
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func parseAny(kind string, doc []byte) error {
	var err error
	switch kind {
	case "request":
		_, err = ParseRequest(doc)
	case "receipt":
		_, err = ParseReceipt(doc)
	default:
		_, err = ParseSubject(doc)
	}
	return err
}

func normalize(t *testing.T, v any) any {
	t.Helper()
	b, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	var out any
	if err := json.Unmarshal(b, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

func TestVectorsFileNamesSourceCommit(t *testing.T) {
	if vectorsSourceCommit != "2684641c719b7c7b3944243f0f9ae1f70a238693" {
		t.Fatal("vector source commit changed without refreshing the copy")
	}
	raw, err := os.ReadFile(vectorsFile)
	if err != nil || !bytes.HasPrefix(raw, []byte("{")) {
		t.Fatalf("vector file unreadable: %v", err)
	}
}

// T1/T2: sealed documents parse, keep their identity, and re-sealing their
// fields reproduces the Tier A hash and id.
func TestGoldenRequests(t *testing.T) {
	v := loadVectors(t)
	if len(v.Documents.Requests) == 0 {
		t.Fatal("no request vectors")
	}
	for _, d := range v.Documents.Requests {
		t.Run(d.Name, func(t *testing.T) {
			req, err := ParseRequest(d.Document)
			if err != nil {
				t.Fatal(err)
			}
			if req.ContentHash != d.Expected.ContentHash || req.RequestID != d.Expected.ID {
				t.Fatalf("identity %s %s", req.ContentHash, req.RequestID)
			}
			var doc any
			_ = json.Unmarshal(d.Document, &doc)
			if !reflect.DeepEqual(normalize(t, req.Dict()), doc) {
				t.Fatalf("round trip differs")
			}
			sealed, err := SealRequest(SealRequestInput{
				Subject: req.Subject, Mode: req.Mode, AuthorActors: req.AuthorActors, Nonce: req.Nonce,
				AuthoringExecutionID: req.AuthoringExecutionID, AuthoringAttemptIDs: req.AuthoringAttemptIDs,
				AuthoringLineageRoot: req.AuthoringLineageRoot, CreatedAt: req.CreatedAt,
			})
			if err != nil {
				t.Fatal(err)
			}
			if sealed.ContentHash != d.Expected.ContentHash || sealed.RequestID != d.Expected.ID {
				t.Fatalf("sealed identity %s %s", sealed.ContentHash, sealed.RequestID)
			}
			// stored and read back
			b, _ := json.Marshal(sealed.Dict())
			back, err := ParseRequest(b)
			if err != nil || back.RequestID != d.Expected.ID {
				t.Fatalf("read back: %v", err)
			}
		})
	}
}

func TestGoldenReceipts(t *testing.T) {
	v := loadVectors(t)
	if len(v.Documents.Receipts) == 0 {
		t.Fatal("no receipt vectors")
	}
	reqs := map[string]ReviewRequest{}
	for _, d := range v.Documents.Requests {
		r, err := ParseRequest(d.Document)
		if err != nil {
			t.Fatal(err)
		}
		reqs[r.RequestID] = r
	}
	for _, d := range v.Documents.Receipts {
		t.Run(d.Name, func(t *testing.T) {
			rc, err := ParseReceipt(d.Document)
			if err != nil {
				t.Fatal(err)
			}
			if rc.ContentHash != d.Expected.ContentHash || rc.ReceiptID != d.Expected.ID {
				t.Fatalf("identity %s %s", rc.ContentHash, rc.ReceiptID)
			}
			var doc any
			_ = json.Unmarshal(d.Document, &doc)
			if !reflect.DeepEqual(normalize(t, rc.Dict()), doc) {
				t.Fatalf("round trip differs")
			}
			if req, ok := reqs[rc.RequestID]; ok {
				sealed, err := SealReceipt(req, SealReceiptInput{
					Outcome: rc.Outcome, Criteria: rc.Criteria, FindingsRef: rc.FindingsRef,
					ReviewerActor: rc.ReviewerActor, ReviewerExecutionID: rc.ReviewerExecutionID,
					AttemptID: rc.AttemptID, LineageRoot: rc.LineageRoot, EvidenceRef: rc.EvidenceRef,
					CreatedAt: rc.CreatedAt,
				})
				if err != nil {
					t.Fatal(err)
				}
				if sealed.ContentHash != d.Expected.ContentHash || sealed.ReceiptID != d.Expected.ID {
					t.Fatalf("sealed identity %s %s", sealed.ContentHash, sealed.ReceiptID)
				}
			}
		})
	}
}

// T3/T4: every refusal vector yields the vector's exact code.
func TestParseRefusals(t *testing.T) {
	v := loadVectors(t)
	sentinels := map[string]*Error{
		CodeMalformed: ErrMalformed, CodeUnknownKey: ErrUnknownKey, CodeBadSubject: ErrBadSubject,
		CodeBadIdentity: ErrBadIdentity, CodeRubricMismatch: ErrRubricMismatch,
		CodePassWithUnobserved: ErrPassWithUnobserved, CodeUnobservedOutcome: ErrUnobservedOutcome,
	}
	for _, d := range v.ParseRefusals {
		t.Run(d.Name, func(t *testing.T) {
			err := parseAny(d.Kind, d.Document)
			var re *Error
			if !errors.As(err, &re) {
				t.Fatalf("want %s, got %v", d.Code, err)
			}
			if re.Code != d.Code {
				t.Fatalf("want %s, got %s (%s)", d.Code, re.Code, re.Message)
			}
			if !errors.Is(err, sentinels[d.Code]) {
				t.Fatalf("errors.Is mismatch for %s", d.Code)
			}
		})
	}
}

func TestParseAcceptances(t *testing.T) {
	v := loadVectors(t)
	for _, d := range v.ParseAcceptances {
		t.Run(d.Name, func(t *testing.T) {
			var got any
			switch d.Kind {
			case "request":
				r, err := ParseRequest(d.Document)
				if err != nil {
					t.Fatal(err)
				}
				got = normalize(t, r.Dict())
			case "receipt":
				r, err := ParseReceipt(d.Document)
				if err != nil {
					t.Fatal(err)
				}
				got = normalize(t, r.Dict())
			default:
				t.Fatalf("kind %s", d.Kind)
			}
			var want any
			_ = json.Unmarshal(d.Normalised, &want)
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("got %v\nwant %v", got, want)
			}
		})
	}
}

// Sealing applies the same bounds as parsing.
func TestSealBoundsMatchParse(t *testing.T) {
	v := loadVectors(t)
	req, err := ParseRequest(v.Documents.Requests[0].Document)
	if err != nil {
		t.Fatal(err)
	}
	in := SealRequestInput{Subject: req.Subject, Mode: req.Mode, Nonce: req.Nonce}
	long := make([]byte, MaxStr+1)
	for i := range long {
		long[i] = 'a'
	}
	in.Nonce = string(long)
	if _, err := SealRequest(in); !errors.Is(err, ErrMalformed) {
		t.Fatalf("long nonce: %v", err)
	}
	in.Nonce = "n"
	for i := 0; i <= MaxActors; i++ {
		in.AuthorActors = append(in.AuthorActors, string(rune('a'+i%26))+string(rune('a'+i/26)))
	}
	if _, err := SealRequest(in); !errors.Is(err, ErrMalformed) {
		t.Fatalf("many actors: %v", err)
	}
	in.AuthorActors = nil
	in.CreatedAt = "yesterday"
	if _, err := SealRequest(in); !errors.Is(err, ErrMalformed) {
		t.Fatalf("created_at: %v", err)
	}
	in.CreatedAt = ""
	bad := in
	bad.Subject.Repository = "nope"
	if _, err := SealRequest(bad); !errors.Is(err, ErrBadSubject) {
		t.Fatalf("subject: %v", err)
	}
	in.Mode = "other"
	if _, err := SealRequest(in); !errors.Is(err, ErrMalformed) {
		t.Fatalf("mode: %v", err)
	}
}

// T5: a manual request forces advisory receipts, whatever the caller does.
func TestSealReceiptManualForcesAdvisory(t *testing.T) {
	v := loadVectors(t)
	req, _ := ParseRequest(v.Documents.Requests[0].Document)
	sealed, err := SealRequest(SealRequestInput{Subject: req.Subject, Mode: ModeManual, Nonce: "m1"})
	if err != nil {
		t.Fatal(err)
	}
	rc, err := SealReceipt(sealed, SealReceiptInput{Outcome: "UNOBSERVABLE", ReviewerActor: "x"})
	if err != nil {
		t.Fatal(err)
	}
	if rc.Assurance != AssuranceAdvisory {
		t.Fatalf("assurance %s", rc.Assurance)
	}
}

// T6/T7: gate vectors.
func TestGateVectors(t *testing.T) {
	v := loadVectors(t)
	if len(v.Gate) == 0 {
		t.Fatal("no gate vectors")
	}
	seen := map[string]bool{}
	for _, g := range v.Gate {
		t.Run(g.Name, func(t *testing.T) {
			var live *ReviewSubject
			if g.Live != nil && string(*g.Live) != "null" {
				s, err := ParseSubject(*g.Live)
				if err != nil {
					t.Fatal(err)
				}
				live = &s
			}
			var req *ReviewRequest
			if g.Request != nil && string(*g.Request) != "null" {
				r, err := ParseRequest(*g.Request)
				if err != nil {
					t.Fatal(err)
				}
				req = &r
			}
			var pool []ReviewReceipt
			for _, raw := range g.Receipts {
				rc, err := ParseReceipt(raw)
				if err != nil {
					t.Fatal(err)
				}
				pool = append(pool, rc)
			}
			got, err := EvaluateReviewGate(live, req, pool, g.RequiredAssurance)
			if g.Expected == "error" {
				if err == nil {
					t.Fatalf("want error, got %q", got)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if got != g.Expected {
				t.Fatalf("got %q want %q", got, g.Expected)
			}
			seen[got] = true
		})
	}
	for _, o := range []string{GateSatisfied, GateChangesRequested, GateNeedsHuman, GateUnobservable, GateStale,
		GateMissing, GateUnknown, GateAdvisoryOnly, GateNotIndependent} {
		if !seen[o] {
			t.Errorf("no vector exercises %s", o)
		}
	}
}

func TestCanonicalJSONMatchesPython(t *testing.T) {
	// Python: json.dumps({"b":"é\u0001\u007f😀\"\\","a":[]}, sort_keys=True, separators=(",",":"))
	got := string(canonicalJSON(map[string]any{"b": "é\x01\x7f😀\"\\", "a": []string{}}))
	want := `{"a":[],"b":"\u00e9\u0001\u007f\ud83d\ude00\"\\"}`
	if got != want {
		t.Fatalf("got %s want %s", got, want)
	}
}

// The list bound applies before de-duplication, as in Tier A.
func TestParseListBoundBeforeDedup(t *testing.T) {
	v := loadVectors(t)
	var doc map[string]any
	if err := json.Unmarshal(v.Documents.Requests[0].Document, &doc); err != nil {
		t.Fatal(err)
	}
	dup := make([]any, MaxActors+1)
	for i := range dup {
		dup[i] = "same"
	}
	doc["author_actors"] = dup
	b, _ := json.Marshal(doc)
	if _, err := ParseRequest(b); !errors.Is(err, ErrMalformed) {
		t.Fatalf("got %v", err)
	}
}
